export function servicePromotionTaskRows(s){const rows=[],add=(x,kind,status,commands,section)=>rows.push({id:`service-promotion:${kind}:${x.id}:${status}`,category:`service-promotion-${kind}`,sourceId:x.id,storeId:x.storeId||x.ownerStoreId||null,bookingId:x.bookingId||null,title:kind==='withdrawal'?'个人服务佣金提现核对':kind==='recovery'?'个人已付佣金扣回':kind==='risk'?'异常服务佣金人工审核':kind==='identity'?'推广个人实名核验':'服务推广邀请确认',status:commands.length?'open':(['paid','closed','loss','rejected','accepted','approved'].includes(status)||kind==='identity'&&status==='verified')?'done':'waiting',statusLabel:status,createdAt:x.createdAt,dueAt:x.dueAt||x.confirmExpiresAt||x.expiresAt||null,requiredRoute:'service-promotion',assignmentMode:'task',sourceToken:digest({id:x.id,version:x.version,status,amount:x.amountCents,received:x.receivedCents,...(kind==='identity'?{identity:x.identity}: {})}),manageRoles:commands.length?['group']:[],allowedJobs:{group:['identity','risk'].includes(kind)?['support']:['finance'],store:[]},routes:{group:`/group/service-promotion/${section}/${x.id}`},commands});for(const risk of s.servicePromotionRisks||[])add(risk,'risk',risk.status,risk.status==='pending'?['service-promotion.risk-review']:[],'risks');for(const r of s.servicePromoters||[]){if(r.status==='identity-pending')add(r,'identity',r.status,['service-promotion.identity-review'],'promoters');else if(['verified','rejected'].includes(r.identity?.status))add(r,'identity',r.identity.status,[],'promoters');}for(const w of s.servicePromotionWithdrawals||[])add(w,'withdrawal',w.status,['requested','failed'].includes(w.status)?['service-promotion.withdraw-pay']:['processing','awaiting_user','cancel_requested'].includes(w.status)?['service-promotion.withdraw-query']:[],'withdrawals');for(const d of s.servicePromotionRecoveries||[])add(d,'recovery',d.status,!debtKnown(s,d)?[]:d.returnPendingCents?['service-promotion.recovery-return']:outstanding(s,d)>0?['service-promotion.recovery-receive',...(s.now>=d.dueAt?['service-promotion.recovery-loss']:[])]:[],'recoveries');return rows;}

// Actual facts for a finance month table. This does not choose a taxable basis or tax rate.
export function servicePromotionMonthlyFacts(s,actor){
  actor=resolveAccountActor(s,actor);if(!finance(actor))throw new Error('只有集团财务可读取个人佣金月度实际资金事实');
  const rows=[],unlocated=[],isAmount=n=>Number.isSafeInteger(n)&&n>=0;
  const person=(key,id)=>{const p=promoter(s,id);return p&&personKey(p)===key?{personKind:p.personKind,personId:p.personId,promoterType:p.promoterType}:null;};
  const add=(value,at)=>{if(!['id','sourceId'].every(k=>typeof value[k]==='string'&&value[k].trim())||!['amountCents','storeCents','groupCents'].every(k=>Number.isSafeInteger(value[k]))||value.storeCents+value.groupCents!==value.amountCents){unlocated.push({...value,month:null,reason:'原编号、金额或承担份额待核对，不能补造月度来源'});return;}if(!Number.isSafeInteger(at)||at<0||at>s.now){unlocated.push({...value,month:null,reason:'实际发生时间待核对，不能按创建月份归入'});return;}rows.push({...value,occurredAt:at,month:day(at).slice(0,7)});};
  for(const w of s.servicePromotionWithdrawals||[]){
    if(w.status!=='paid')continue;
    const identity=person(w.personKey,w.promoterId),allocations=w.allocations||[];
    const valid=identity&&isAmount(w.amountCents)&&allocations.length&&sum(allocations,a=>a.amountCents)===w.amountCents&&allocations.every(a=>{const c=commission(s,a.commissionId);return c?.personKey===w.personKey&&isAmount(a.amountCents)&&isAmount(a.storeCents)&&isAmount(a.groupCents)&&a.storeCents+a.groupCents===a.amountCents;});
    if(!valid){unlocated.push({id:w.id,kind:'payment',sourceId:w.id,amountCents:isAmount(w.amountCents)?w.amountCents:null,month:null,reason:'实际已付款与佣金明细来源不一致，待核对'});continue;}
    for(const a of allocations){const c=commission(s,a.commissionId);add({id:`${w.id}:${a.commissionId}`,kind:'payment',sourceId:w.id,commissionId:c.id,bookingId:c.bookingId,paymentId:c.paymentId,storeId:c.storeId,...identity,amountCents:a.amountCents,storeCents:a.storeCents,groupCents:a.groupCents},w.execution?.proof?.occurredAt);}
  }
  for(const o of s.servicePromotionOffsets||[]){
    const c=commission(s,o.commissionId),d=(s.servicePromotionRecoveries||[]).find(x=>x.id===o.recoveryId),identity=person(o.personKey,o.promoterId);
    if(!identity||c?.personKey!==o.personKey||d?.personKey!==o.personKey||!isAmount(o.amountCents)||!isAmount(o.sourceStoreCents)||!isAmount(o.sourceGroupCents)||o.sourceStoreCents+o.sourceGroupCents!==o.amountCents){unlocated.push({id:o.id,kind:'offset',sourceId:o.id,amountCents:isAmount(o.amountCents)?o.amountCents:null,month:null,reason:'抵扣原佣金或债务来源待核对'});continue;}
    const base={commissionId:c.id,bookingId:c.bookingId,paymentId:c.paymentId,storeId:c.storeId,recoveryId:d.id,...identity};
    add({id:o.id,kind:'offset',sourceId:o.id,...base,amountCents:o.amountCents,storeCents:o.sourceStoreCents,groupCents:o.sourceGroupCents},o.createdAt);
    for(const r of o.reversals||[])add({id:r.id,kind:'offset-reversal',sourceId:o.id,...base,amountCents:-r.amountCents,storeCents:-r.sourceStoreCents,groupCents:-r.sourceGroupCents},r.at);
  }
  for(const d of s.servicePromotionRecoveries||[]){
    const identity=person(d.personKey,d.promoterId),c=commission(s,d.commissionId);
    for(const r of d.records||[]){const sign=r.kind==='return'?-1:1,base={id:r.id,kind:r.kind==='cash'?'recovery-cash':r.kind==='return'?'recovery-return':r.kind,sourceId:d.id,commissionId:d.commissionId,bookingId:d.bookingId,paymentId:d.paymentId,storeId:d.storeId,...identity,amountCents:sign*r.amountCents,storeCents:sign*r.storeCents,groupCents:sign*r.groupCents};if(!identity||c?.personKey!==d.personKey||!Number.isSafeInteger(base.amountCents)||!Number.isSafeInteger(base.storeCents)||!Number.isSafeInteger(base.groupCents)||base.storeCents+base.groupCents!==base.amountCents){unlocated.push({...base,month:null,reason:'原收回、退回或损失分摊来源待核对'});continue;}add(base,['cash','return','loss'].includes(r.kind)?r.occurredAt:r.at);}
  }
  return clone({taxTreatment:'unconfigured',taxRate:null,rows,unlocated});
}
